{{ (() => {
  const startText = StartTime.text.trim();
  const duration = Number(Duration.text);
  const toMinutes = t => Number(t.slice(0, 2)) * 60 + Number(t.slice(3, 5));
  const answer = (available, code, message) => storeValue('roomDecision', {available, code, message}, false);
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(startText)) return answer(false, 'INVALID', 'Validation error — enter a start time in HH:MM format.');
  if (!Number.isInteger(duration) || duration < 1 || duration > 120) return answer(false, 'INVALID', 'Validation error — duration must be 1 to 120 minutes.');
  const start = toMinutes(startText), end = start + duration;
  if (start <= 510) return answer(false, 'INVALID', 'Validation error — start time must be after 08:30.');
  if (end > 1440) return answer(false, 'INVALID', 'Validation error — the interval must end by midnight.');
  if (RoomStatus.isSwitchedOn) return answer(false, 'BLOCKED', 'Unavailable — Room 101 is blocked.');
  for (const slot of [MorningBooking.text, NoonBooking.text]) {
    if (start < toMinutes(slot.slice(6,11)) && end > toMinutes(slot.slice(0,5))) return answer(false, 'OVERLAP', 'Unavailable — overlaps the ' + slot.slice(0,11) + ' booking.');
  }
  return answer(true, 'FREE', 'Available — Room 101 is free for this interval.');
})() }}

